package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchDocuments handles full-text search with filtering
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	query := r.URL.Query().Get("q")
	category := r.URL.Query().Get("cat")
	sortField := r.URL.Query().Get("sort")

	if query == "" {
		http.Error(w, "Missing search query", 400)
		return
	}

	// Sanitize query for full-text search
	query = strings.ReplaceAll(query, "'", "''")

	// Build dynamic SQL based on parameters
	sqlStmt := fmt.Sprintf(
		"SELECT id, title, body, created_at FROM documents WHERE to_tsvector('english', body) @@ plainto_tsquery('english', '%s')",
		query,
	)

	if category != "" {
		// Category filter - uses parameterized approach
		sqlStmt += " AND category_id = $1"
	}

	// Sort field is directly interpolated - VULNERABLE
	if sortField != "" {
		sqlStmt += " ORDER BY " + sortField
	} else {
		sqlStmt += " ORDER BY created_at DESC"
	}

	sqlStmt += " LIMIT 50"

	var rows *sql.Rows
	var err error

	if category != "" {
		rows, err = db.Query(sqlStmt, category)
	} else {
		rows, err = db.Query(sqlStmt)
	}

	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var title, body, createdAt string
		if err := rows.Scan(&id, &title, &body, &createdAt); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(",\n"))
		}
		first = false
		line := fmt.Sprintf(`  {"id":%d,"title":"%s","body":"%s","created_at":"%s"}`,
			id, strings.ReplaceAll(title, `"`, `\"`), strings.ReplaceAll(body, `"`, `\"`), createdAt)
		w.Write([]byte(line))
	}
	w.Write([]byte("\n]"))
}

// healthCheck for liveness probes
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchDocuments)
	http.HandleFunc("/healthz", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
